-- 조안나T 초안 검토 반영: 4장 수정 (012 차티스트, 022 조례·규칙, 028 3심제, 046 헌법 소원 대상)
begin;
update public.cards set question='19세기 영국 노동자들이 벌인 차티스트 운동과 관련 깊은 기본권은?', answer='참정권', wrong=array['사회권', '청구권', '자유권'], explanation='차티스트 운동은 노동자들이 선거권 확대를 요구한 운동으로, 국가의 의사 결정에 참여할 권리인 참정권과 관련 깊다.' where id='social-jo-012' and question='노동자들이 선거권을 요구한 차티스트 운동과 관련 깊은 기본권은?';
update public.cards set question='법률은 국회, 명령은 행정부가 만든다. 조례와 규칙을 만드는 기관을 차례로 알맞게 나열한 것은?', answer='지방 의회–자치 단체장', wrong=array['자치 단체장–지방 의회', '지방 의회–행정부', '국회–자치 단체장'], explanation='법률은 국회, 명령은 행정부가 만드는 중앙 차원의 법이고, 조례는 지방 의회, 규칙은 지방 자치 단체장(지방 행정부)이 만드는 지방 차원의 법이다.' where id='social-jo-022' and question='법률은 국회, 명령은 행정부가 만든다. 조례 A, 규칙 B를 만드는 곳은?';
update public.cards set question='일반적인 민사·형사 재판의 3심제에서 1심 A, 2심 B를 맡는 법원은? A–B는?', answer='지방 법원–고등 법원', wrong=array['가정 법원–고등 법원', '지방 법원–대법원', '고등 법원–대법원'], explanation='일반적인 민사·형사 재판에서 1심은 지방 법원, 2심은 고등 법원, 3심은 대법원이 맡는다. 가정 법원은 가사·소년 사건을 맡는 전문 법원이라 일반 재판의 1심이 아니다.' where id='social-jo-028' and question='3심제에서 1심 A, 3심 B를 맡는 법원은? A–B는?';
update public.cards set question='기본권을 침해당했다며 헌법 소원 심판을 청구할 때, 그 대상이 될 수 없는 것은?', answer='법원의 재판', wrong=array['국회가 만든 법률', '경찰의 공권력 행사', '시험 응시 나이 제한 규정'], explanation='헌법 소원은 공권력으로 기본권을 침해당한 국민이 청구한다. 법률이나 시험 규정, 경찰의 공권력 행사도 대상이 될 수 있지만, 법원의 재판은 헌법 소원의 대상에서 제외된다.' where id='social-jo-046' and question='헌법재판소가 담당하는 심판으로 옳지 않은 것은?';
do $v$ begin if (select count(*) from public.cards where id in ('social-jo-012', 'social-jo-022', 'social-jo-028', 'social-jo-046') and question in ('19세기 영국 노동자들이 벌인 차티스트 운동과 관련 깊은 기본권은?', '법률은 국회, 명령은 행정부가 만든다. 조례와 규칙을 만드는 기관을 차례로 알맞게 나열한 것은?', '일반적인 민사·형사 재판의 3심제에서 1심 A, 2심 B를 맡는 법원은? A–B는?', '기본권을 침해당했다며 헌법 소원 심판을 청구할 때, 그 대상이 될 수 없는 것은?')) <> 4 then raise exception 'update mismatch'; end if; end $v$;
commit;
